<?php require_once __DIR__.'/../includes/functions.php';need_role(['admin_utama']);if($_SERVER['REQUEST_METHOD']!=='POST')go('/laporwarga/admin-utama/pengguna.php');check_csrf();$id=(int)($_POST['id_user']??0);$active=(int)($_POST['status_akun']??0);if(!in_array($active,[0,1],true)||$id===me()['id_user']){flash('error','Perubahan akun tidak valid.');go('/laporwarga/admin-utama/pengguna.php');}$s=db()->prepare("UPDATE users SET status_akun=?,updated_at=NOW() WHERE id_user=? AND role IN ('masyarakat','petugas')");$s->execute([$active,$id]);log_activity('ubah_status_pengguna','id='.$id.' status='.$active);flash('success','Status akun diperbarui.');go('/laporwarga/admin-utama/pengguna.php');